@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Shipment Management</h2>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
    <select class="form-select w-auto" @bind="filterStatus">
        <option value="">All Statuses</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <button class="btn btn-primary text-nowrap" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>@(editingShipment?.Id > 0 ? "Edit" : "Create") Shipment</h5>
            <EditForm Model="editingShipment" OnValidSubmit="SaveShipment" FormName="shipmentForm">
                <DataAnnotationsValidator />
                <div class="row g-2 mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Tracking Number</label>
                        <InputText class="form-control" @bind-Value="editingShipment!.TrackingNumber" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Origin</label>
                        <InputText class="form-control" @bind-Value="editingShipment!.Origin" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">Destination</label>
                        <InputText class="form-control" @bind-Value="editingShipment!.Destination" />
                    </div>
                </div>
                <div class="row g-2 mb-2">
                    <div class="col-md-3">
                        <label class="form-label">Status</label>
                        <InputSelect class="form-select" @bind-Value="editingShipment!.Status">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </InputSelect>
                    </div>
                    <div class="col-md-3">
                        <label class="form-label">Shipped Date</label>
                        <InputDate class="form-control" @bind-Value="editingShipment!.ShippedDate" />
                    </div>
                    <div class="col-md-3">
                        <label class="form-label">Est. Delivery</label>
                        <InputDate class="form-control" @bind-Value="editingShipment!.EstimatedDelivery" />
                    </div>
                    <div class="col-md-3">
                        <label class="form-label">Customer Email</label>
                        <InputText class="form-control" @bind-Value="editingShipment!.CustomerEmail" />
                    </div>
                </div>
                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <InputText class="form-control" @bind-Value="editingShipment!.Description" />
                </div>
                <button type="submit" class="btn btn-success me-2">Save</button>
                <button type="button" class="btn btn-secondary" @onclick="CancelForm">Cancel</button>
            </EditForm>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments match the current filter.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Customer</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>@s.CustomerEmail</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary me-1" @onclick="() => EditShipment(s)">Edit</button>
                            <button class="btn btn-sm btn-outline-danger" @onclick="() => DeleteShipment(s.Id)">Delete</button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string filterStatus = "";
    private bool showForm;
    private ShipmentDto? editingShipment;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments?
        .Where(s => string.IsNullOrEmpty(filterText) ||
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(filterStatus) ||
                    s.Status.ToString() == filterStatus)
        ?? Enumerable.Empty<ShipmentDto>();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments");
    }

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto
        {
            TrackingNumber = $"TRK-{DateTime.Now:yyyyMMdd}-{Random.Shared.Next(100, 999)}",
            ShippedDate = DateTime.Today,
            EstimatedDelivery = DateTime.Today.AddDays(7)
        };
        showForm = true;
    }

    private void EditShipment(ShipmentDto shipment)
    {
        editingShipment = new ShipmentDto
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            ShippedDate = shipment.ShippedDate,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail,
            Description = shipment.Description
        };
        showForm = true;
    }

    private async Task SaveShipment()
    {
        if (editingShipment is null) return;

        if (editingShipment.Id > 0)
        {
            await Http.PutAsJsonAsync($"api/shipments/{editingShipment.Id}", editingShipment);
        }
        else
        {
            await Http.PostAsJsonAsync("api/shipments", editingShipment);
        }

        showForm = false;
        editingShipment = null;
        await LoadShipments();
    }

    private void CancelForm()
    {
        showForm = false;
        editingShipment = null;
    }

    private async Task DeleteShipment(int id)
    {
        await Http.DeleteAsync($"api/shipments/{id}");
        await LoadShipments();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Track My Shipments</PageTitle>

<h2>My Shipments</h2>

<div class="row mb-4">
    <div class="col-md-8">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">
                Track
            </button>
        </div>
    </div>
</div>

@if (trackedShipment is not null)
{
    <div class="card mb-4 border-primary">
        <div class="card-header bg-primary text-white">
            <strong>@trackedShipment.TrackingNumber</strong> — @trackedShipment.Description
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @trackedShipment.Origin</p>
                    <p><strong>To:</strong> @trackedShipment.Destination</p>
                    <p><strong>Shipped:</strong> @trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(trackedShipment.Status) fs-6">@GetStatusDisplayText(trackedShipment.Status)</span></p>
                    <p><strong>Estimated Delivery:</strong> @trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                    @{
                        var daysRemaining = (trackedShipment.EstimatedDelivery - DateTime.Today).Days;
                    }
                    <p><strong>Days Remaining:</strong>
                        @if (trackedShipment.Status == ShipmentStatus.Delivered)
                        {
                            <span class="text-success">Delivered!</span>
                        }
                        else if (daysRemaining < 0)
                        {
                            <span class="text-danger">@Math.Abs(daysRemaining) day(s) overdue</span>
                        }
                        else
                        {
                            <span>@daysRemaining day(s)</span>
                        }
                    </p>
                </div>
            </div>
            <!-- Progress bar -->
            <div class="mt-3">
                <div class="progress" style="height: 25px;">
                    <div class="progress-bar @GetProgressBarClass(trackedShipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercentage(trackedShipment.Status)%"
                         aria-valuenow="@GetProgressPercentage(trackedShipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @GetStatusDisplayText(trackedShipment.Status)
                    </div>
                </div>
            </div>
        </div>
    </div>
}
else if (trackingError is not null)
{
    <div class="alert alert-warning">@trackingError</div>
}

<h3 class="mt-4">My Shipments</h3>

@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <p>You have no shipments on record.</p>
}
else
{
    <div class="row">
        @foreach (var s in myShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100 @(s.Status == ShipmentStatus.Delivered ? "border-success" : s.Status == ShipmentStatus.Delayed ? "border-danger" : "")">
                    <div class="card-body">
                        <h6 class="card-title">@s.TrackingNumber</h6>
                        <p class="card-text text-muted mb-1">@s.Description</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1">
                            <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                        </p>
                        <p class="mb-0"><small>Est. Delivery: @s.EstimatedDelivery.ToString("MMM dd, yyyy")</small></p>
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-sm btn-outline-primary" @onclick="() => ViewDetails(s.TrackingNumber)">
                            View Details
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? myShipments;
    private ShipmentDto? trackedShipment;
    private string trackingNumber = "";
    private string? trackingError;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/my");
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        trackingError = null;
        trackedShipment = null;

        var response = await Http.GetAsync($"api/shipments/track/{trackingNumber.Trim()}");
        if (response.IsSuccessStatusCode)
        {
            trackedShipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
        }
        else
        {
            trackingError = $"No shipment found with tracking number '{trackingNumber}'.";
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private void ViewDetails(string tracking)
    {
        trackingNumber = tracking;
        _ = TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetStatusDisplayText(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending Pickup",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Delayed => "Delayed",
        _ => "Unknown"
    };

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger progress-bar-striped progress-bar-animated",
        ShipmentStatus.InTransit => "bg-primary progress-bar-striped progress-bar-animated",
        _ => "bg-info progress-bar-striped progress-bar-animated"
    };
}

